import{_ as r,C as s,c as a,o as i,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Print documents","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/print-documents.md","filePath":"master/supply-chain/inventories/operations/print-documents.md","lastUpdated":1792041590000}'),l={name:"master/supply-chain/inventories/operations/print-documents.md"};function d(p,t,h,g,c,u){const n=s("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="print-documents" tabindex="-1">Print documents <a class="header-anchor" href="#print-documents" aria-label="Permalink to &quot;Print documents&quot;">​</a></h1><p>From any transfer you can print the papers that go with the goods: a picking list, a delivery slip, package labels and product labels. All of them sit in one <strong>Print</strong> menu.</p><blockquote><p><strong>In simple words:</strong> Click <strong>Print</strong>, pick the paper you need, and Aureus makes a PDF.</p></blockquote><p>Open a transfer and click <strong>Print</strong> in the header.</p>',4)),o(n,{src:"/images1/inventory/prt_menu.png",alt:"Print menu on a done receipt with Picking Operations, Delivery Slip, Packages and Labels"}),t[1]||(t[1]=e('<h2 id="the-print-menu" tabindex="-1">The print menu <a class="header-anchor" href="#the-print-menu" aria-label="Permalink to &quot;The print menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Use</th></tr></thead><tbody><tr><td><strong>Picking Operations</strong></td><td>A list for the person who collects the goods.</td></tr><tr><td><strong>Delivery Slip</strong></td><td>A paper that travels with the parcel.</td></tr><tr><td><strong>Packages</strong></td><td>A sheet for the packages in the transfer.</td></tr><tr><td><strong>Labels</strong></td><td>Labels for products or lots. Opens the <strong>Labels</strong> window.</td></tr></tbody></table><p>The menu has exactly these four options.</p><h2 id="display-on-delivery-slips" tabindex="-1">Display on Delivery Slips <a class="header-anchor" href="#display-on-delivery-slips" aria-label="Permalink to &quot;Display on Delivery Slips&quot;">​</a></h2><p>To show lot and serial numbers on the delivery slip:</p><ol><li>Go to <code>Inventory → Settings → Manage Traceability</code>.</li><li>Turn on <strong>Lots &amp; Serial Numbers</strong>.</li><li>Turn on <strong>Display on Delivery Slips</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol><h2 id="print-labels" tabindex="-1">Print labels <a class="header-anchor" href="#print-labels" aria-label="Permalink to &quot;Print labels&quot;">​</a></h2><ol><li>Click <strong>Print</strong>, then <strong>Labels</strong>. The window titled <strong>Labels</strong> opens.</li><li>If the transfer has no lot lines, the window has one step, <strong>01 Layout Of Labels</strong>. If it has lot lines, a <strong>Type Of Labels</strong> step comes first: <strong>Product Labels</strong> or <strong>Lot/SN Labels</strong>. Click next.</li><li>Choose <strong>Quantity To Print</strong> from the dropdown: <strong>Operation Quantity</strong> (the default) or <strong>Custom Quantity</strong>.</li><li>Choose the <strong>Format</strong> with the radio buttons.</li><li>Click <strong>Submit</strong>. Click <strong>Cancel</strong> to close the window.</li></ol>',8)),o(n,{src:"/images1/inventory/prt_labels_wizard.png",alt:"Labels window at step 01 Layout Of Labels with Quantity To Print set to Operation Quantity and Format 2x7 with price selected"}),t[2]||(t[2]=e('<h3 id="quantity-to-print" tabindex="-1">Quantity to print <a class="header-anchor" href="#quantity-to-print" aria-label="Permalink to &quot;Quantity to print&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Label type</th><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td>Product</td><td><strong>Operation Quantity</strong></td><td>One label per unit on the transfer.</td></tr><tr><td>Product</td><td><strong>Custom Quantity</strong></td><td>You type a <strong>Quantity</strong>, from 1 to 100.</td></tr><tr><td>Lot/SN</td><td><strong>One per lot/SN</strong></td><td>One label per lot or serial number.</td></tr><tr><td>Lot/SN</td><td><strong>One per unit</strong></td><td>One label per unit.</td></tr></tbody></table><h3 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats&quot;">​</a></h3><ul><li>Product labels: <strong>Dymo</strong>, <strong>2x7 with price</strong>, <strong>4x7 with price</strong>, <strong>4x12</strong> and <strong>4x12 with price</strong>. The default is <strong>2x7 with price</strong>.</li><li>Lot/SN labels: <strong>4x12</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <strong>Type Of Labels</strong> step shows only when <strong>Lots &amp; Serial Numbers</strong> is on and at least one line has a lot.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>Printing never changes the state. You can print in any state, including <strong>Done</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./stock-moves-and-lots.html">Stock moves and lots</a></li><li><a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../tracking/packages.html">Packages</a></li><li><a href="./">Transfers</a></li></ul>',9))])}const y=r(l,[["render",d]]);export{b as __pageData,y as default};
